var cands=G.AltDB.find(DATA.original.split(' ')[0]);
var hits=cands.filter(function(x){return x.original===DATA.original;});
assert(hits.length>=1,'find returns the record for "'+DATA.original+'"');
var r=hits[0];
var cmp=G.AltDB.compare(r.original, r.alternative);
assert(cmp.winner,'comparison picks a winner');
assert(cmp.details.length>=2,'comparison covers 2+ metrics');
log('alternative to '+r.original+': '+r.alternative+' -> winner: '+cmp.winner+' ('+cmp.details.length+' metrics)');

